contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function driving c and asserting the invariant
    function run(uint firstDeposit, uint secondDeposit) public payable {
        // We will send Ether to c using the provided deposit amounts. Ensure this contract
        // has enough balance to perform the payments.
        require(address(this).balance >= firstDeposit + secondDeposit);

        // 1) Make an initial deposit of firstDeposit from this test contract to c
        c.deposit{value: firstDeposit}();

        // 2) Make a second deposit of secondDeposit (could be zero)
        c.deposit{value: secondDeposit}();

        // Record c's balance before withdrawAll
        uint beforeCBalance = address(c).balance;

        // Try to call withdrawAll and capture whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the withdrawAll attempt, the caller (this contract) may or may not have
        // received funds. We check the observable effects on c: either its balance is
        // unchanged if withdrawAll reverted, or it decreased by the amount of cleared credit
        // and a subsequent withdrawAll should behave accordingly. To observe the caller's
        // remaining credit we attempt another withdrawAll and see whether it would revert
        // (i.e., whether there is remaining credit to send).

        // Record c balance after first withdraw attempt
        uint afterCBalance = address(c).balance;

        // Attempt a second withdraw and record whether it reverts
        bool revertedSecond;
        try c.withdrawAll() {
            revertedSecond = false;
        } catch {
            revertedSecond = true;
        }

        // General rule asserted:
        // If the first withdrawAll reverted, then c's balance must be unchanged and
        // the second withdrawAll's revert-ness equals the first (no state change happened).
        // Otherwise (first succeeded), c's balance decreased (or stayed the same if cleared credit was zero),
        // and the second withdrawAll must revert (caller credit was cleared to zero).
        assert(
            (reverted && afterCBalance == beforeCBalance && revertedSecond == reverted)
            ||
            (!reverted && afterCBalance <= beforeCBalance && revertedSecond == true)
        );
    }

    // Allow receiving Ether when c sends funds back
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function driving c and asserting the invariant
    function run(uint depositAmount) public payable {
        // ensure this test contract has enough balance to deposit
        require(address(this).balance >= depositAmount);

        // Make a deposit of depositAmount from this test contract to c
        c.deposit{value: depositAmount}();

        // Record c's balance before withdraw
        uint beforeCBalance = address(c).balance;

        // Attempt withdrawAll and record whether it reverted
        bool firstReverted;
        try c.withdrawAll() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // Record c balance after first withdraw attempt
        uint afterFirstCBalance = address(c).balance;

        // Attempt a second withdrawAll and record whether it reverts
        bool secondReverted;
        try c.withdrawAll() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // General rule asserted:
        // If the first withdrawAll reverted, then c's balance must be unchanged (no funds moved)
        // and the second withdrawAll must also revert (no state changed to enable a withdraw).
        // Otherwise (first succeeded), c's balance must have not increased (it either stayed the same if depositAmount==0,
        // or decreased by at most depositAmount), and the second withdrawAll must revert (credit cleared).
        assert(
            (firstReverted && afterFirstCBalance == beforeCBalance && secondReverted)
            ||
            (!firstReverted && afterFirstCBalance <= beforeCBalance && secondReverted)
        );
    }

    // Allow receiving Ether when c sends funds back
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We use a single public payable test function that takes no inputs.
    // It checks behavior of withdrawAll when this caller's recorded credit is zero.
    function run() public payable {
        // Ensure this test contract currently has zero recorded credit in c by not making any deposit.
        // read address balances before the call
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        bool reverted;
        // Call withdrawAll and catch if it reverts
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule: if the caller had zero recorded credit then withdrawAll must not change either balance.
        // We can only observe recorded credit effect indirectly; since we never deposited, recorded credit is zero.
        // So assert that balances are unchanged, regardless of revert.
        assert(afterC == beforeC && afterThis == beforeThis && reverted == false || afterC == beforeC && afterThis == beforeThis && reverted == true);
    }

    // Accept Ether in case c tries to send any (should not happen in this test)
    receive() external payable {}
}
